import { finding } from '../../engine/checks/helpers/findings.mjs';

const LIMIT = 200;

// Converted from authoring-agent-docs: "Target under 200 lines per CLAUDE.md;
// longer files consume more context and reduce adherence." Directional → advisory.
const rule = {
  id: 'claude-md-length',
  severity: 'advisory',
  description: 'A CLAUDE.md over ~200 lines costs context and reduces adherence',
  doc: 'skills/authoring-agent-docs/SKILL.md',
  why: 'everything in CLAUDE.md loads every session; past ~200 lines it crowds out the rules that matter',

  run(ctx) {
    // Root CLAUDE.md only — the one that definitely loads every session. A nested
    // or fixture CLAUDE.md may never load, so flagging its length would be a false
    // positive (an adversarial-mining finding).
    const text = ctx.read('CLAUDE.md');
    if (text === null) return [];
    const lines = text.split('\n').length;
    if (lines <= LIMIT) return [];
    return [finding(rule, {
      file: 'CLAUDE.md', line: LIMIT + 1,
      what: `${lines} lines (target under ${LIMIT})`,
      fix: 'move multi-step procedures to skills and part-of-repo rules to path-scoped packs; keep CLAUDE.md to always-true facts',
    })];
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';

// Converted from engineering-practices: a GENERATED file gets a `merge=ours`
// .gitattributes entry so a conflicting merge resolves automatically instead of
// being hand-edited (which desyncs it from its source). Directional → advisory.
function globToRe(glob) {
  return new RegExp(
    `^${glob.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.')}$`
  );
}

const rule = {
  id: 'generated-merge-driver',
  severity: 'advisory',
  description: 'A GENERATED file needs a .gitattributes merge=ours entry',
  doc: 'skills/engineering-practices/SKILL.md',
  why: 'without merge=ours a conflicting merge on a generated file gets hand-resolved and desyncs from its source',

  run(ctx) {
    // allFiles, not files: this is the one check that reasons *about* generated files,
    // so it must see them even when a repo also marks them linguist-generated (which
    // the engine otherwise drops from ctx.files).
    const generated = ctx.allFiles.filter((f) => f.split('/').pop().includes('GENERATED'));
    if (!generated.length) return [];
    const patterns = (ctx.read('.gitattributes') || '')
      .split('\n')
      .filter((l) => /\bmerge=ours\b/.test(l) && !l.trim().startsWith('#'))
      .map((l) => globToRe(l.trim().split(/\s+/)[0]));

    return generated
      .filter((f) => !patterns.some((re) => re.test(f) || re.test(f.split('/').pop())))
      .map((f) => finding(rule, {
        file: f,
        what: 'a GENERATED file with no merge=ours .gitattributes entry',
        fix: `add \`${f.split('/').pop()} merge=ours\` to .gitattributes (plus a one-time \`git config merge.ours.driver true\`) so a conflicting merge auto-resolves`,
      }));
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';

// Flat-literal count — raw bytes, comments included, no regex. A value wrapped
// across a line break is invisible here (as it is to a grep/sed rename too), so a
// guarded value must stay on one line wherever it appears.
function countOccurrences(text, value) {
  let n = 0;
  let pos = 0;
  while ((pos = text.indexOf(value, pos)) !== -1) {
    n += 1;
    pos += value.length;
  }
  return n;
}

// Module technologies whose files can `import` a shared definition from one
// another (the JS/TS family). A shared-constant only earns its keep for a value
// copied across files that CAN'T share an import — JSON manifests, a YAML
// workflow + a JS module, prod code + a config file. When every watched file is
// one of these, the copy is redundant: export the value once and import it.
const IMPORTABLE_EXTENSIONS = new Set([
  'js', 'mjs', 'cjs', 'jsx', 'ts', 'tsx', 'mts', 'cts',
]);

function fileExtension(path) {
  const base = path.slice(path.lastIndexOf('/') + 1);
  const dot = base.lastIndexOf('.');
