import { finding } from '../../engine/checks/helpers/findings.mjs';
import { findExtensionManifest } from '../../engine/checks/helpers/chrome-manifest.mjs';
import { requestedPermissions } from './lib/manifest-permissions.mjs';

// Fires only on a permission THIS change adds: the store's per-permission
// justification lives on the dashboard, off-repo and manual, so the proactive
// tracking issue beats the reactive publish failure — and with no in-repo
// artifact to clear a block against, advisory is the honest severity.
// Permission SETS are compared against the base, not the text diff: appending a
// JSON array element re-touches the prior element's line (trailing comma).
const rule = {
  id: 'cer/permission-added-store-issue',
  severity: 'advisory',
  description: 'A permission added to the manifest needs a manual store-dashboard justification — open a tracking issue',
  doc: 'packs/chrome-extension-release/RELEASE.md',
  scope: 'work',
  why: 'the store requires a written justification per permission and blocks publishing the new version until the dashboard carries it; that step is manual, so a proactive issue beats the reactive publish failure',

  run(work) {
    const manifestPath = findExtensionManifest(work);
    if (!manifestPath) return [];
    const { head, base } = work.jsonPair(manifestPath);
    if (!head) return [];
    const baseSet = new Set(base ? requestedPermissions(base) : []);
    return requestedPermissions(head)
      .filter((p) => !baseSet.has(p))
      .map((p) =>
        finding(rule, {
          file: manifestPath,
          what: `this change adds the "${p}" permission`,
          fix: `open a tracking issue for the manual Chrome Web Store dashboard step: the Privacy-practices tab needs a written justification for "${p}" before the next publish (daily or manual) can ship — it cannot be automated`,
        })
      );
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { findExtensionManifest } from '../../engine/checks/helpers/chrome-manifest.mjs';
import { requestedPermissions } from './lib/manifest-permissions.mjs';

const PRIVACY = 'dev/build/release/store_artifacts/PRIVACY.md';

// Test the world: at all times, every permission the manifest requests must be
// disclosed in the privacy document — the one release artifact that stays in the
// repo (it is deployed verbatim as the public privacy policy). Whole-repo scope:
// it reads the current manifest and PRIVACY.md, not the diff, so drift in either
// direction surfaces regardless of what this change happened to touch.
const rule = {
  id: 'cer/privacy-permission-alignment',
  severity: 'blocking',
  description: 'Every manifest permission is disclosed in the privacy document',
  doc: 'packs/chrome-extension-release/RELEASE.md',
  why: 'the deployed privacy policy must disclose everything the extension can access; an undisclosed permission is a store-review and trust failure',

  run(ctx) {
    const manifestPath = findExtensionManifest(ctx);
    if (!manifestPath) return [];
    let manifest;
    try { manifest = JSON.parse(ctx.read(manifestPath)); } catch { return []; }
    const privacy = ctx.read(PRIVACY);
    if (privacy === null) return []; // cer/release-layout already flags the missing privacy doc
    return requestedPermissions(manifest)
      .filter((p) => !privacy.includes(p))
      .map((p) =>
        finding(rule, {
          file: PRIVACY,
          what: `manifest requests "${p}" but the privacy document does not mention it`,
          fix: `disclose what "${p}" accesses in PRIVACY.md, so the deployed privacy policy reflects what the extension can reach`,
        })
      );
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';

const rule = {
  id: 'cer/readme-sections',
  severity: 'blocking',
  description: 'The README carries the standard Install and Releasing sections',
  doc: 'packs/chrome-extension-release/RELEASE.md',
  why: 'every extension repo documents install and release the same way, from the standard template',

  run(ctx) {
    const readme = ctx.read('README.md');
    if (readme === null) {
      return [finding(rule, {
        file: 'README.md', what: 'missing',
        fix: 'add a README with the standard Install and Releasing sections',
      })];
    }
    const out = [];
    for (const section of ['Install', 'Releasing']) {
      if (!new RegExp(`^##\\s+${section}\\b`, 'm').test(readme)) {
        out.push(finding(rule, {
          file: 'README.md',
          what: `missing the standard "## ${section}" section`,
          fix: 'copy it from the README template in the release standard and fill in the repo values',
        }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';

// `.github/release.config` is REQUIRED and fully explicit — every extension repo
// declares its release values, there are no silent defaults (a default that
// "happens to match" a repo's layout is a drift risk: change the default, or the
// thing it assumed, and the repo ships the wrong artifact with no signal). This
// check enforces the file's presence, that exactly the required keys are set,
// and that no unknown (typo'd) key sneaks in. Keep REQUIRED_KEYS in sync with
// .github/actions/read-release-config/read-config.mjs. Two things are NOT keys —
// they are forced-uniform structure, not a per-repo choice: the build is always
// `npm run build`, and the zip lives at `dist/<kebab repo name>.zip` (so both
// `zip_path` and `zip_name` are derived, not configured).
const REQUIRED_KEYS = [
  'manifest_path',
  'package_json_path',
  'setup_command',
  'test_command',
  'ship_paths',
];

const rule = {
  id: 'cer/release-config',
  severity: 'blocking',
  description: '.github/release.config exists and sets exactly the required release keys',
  doc: 'packs/chrome-extension-release/RELEASE.md',
  why: 'the release config is explicit with no defaults — a missing/typo\'d key would ship the wrong thing with no signal',

  run(ctx) {
    const path = '.github/release.config';
    const text = ctx.read(path);
    if (text === null) {
      return [finding(rule, {
        file: path,
        what: 'missing — the release config is required and fully explicit (no defaults)',
        fix: `create it with the required keys: ${REQUIRED_KEYS.join(', ')}`,
      })];
    }

    const out = [];
    const seen = new Set();
    text.split('\n').forEach((raw, i) => {
      const line = raw.trim();
      if (!line || line.startsWith('#')) return;
      const eq = line.indexOf('=');
      if (eq === -1) {
        out.push(finding(rule, {
          file: path, line: i + 1,
          what: `line is not KEY=value or a # comment: "${line}"`,
          fix: 'use dotenv syntax — KEY=value, one per line',
        }));
        return;
      }
      const key = line.slice(0, eq).trim();
      if (!REQUIRED_KEYS.includes(key)) {
        out.push(finding(rule, {
          file: path, line: i + 1,
          what: `unknown key "${key}"`,
          fix: `valid keys: ${REQUIRED_KEYS.join(', ')}`,
        }));
      }
      seen.add(key);
    });

    for (const key of REQUIRED_KEYS) {
      if (!seen.has(key)) {
        out.push(finding(rule, {
          file: path,
          what: `missing required key "${key}"`,
          fix: `add "${key}=..." (every key is explicit; "setup_command=" may be empty to mean no install)`,
        }));
      }
    }
    return out;
  },
};

export default rule;

