    for (const call of ORCHESTRATOR_CALLS) {
      if (!text.includes(`./.github/workflows/${call}`)) {
        out.push(finding(rule, {
          file: path,
          what: `does not call the local reusable workflow ./.github/workflows/${call}`,
          fix: `re-copy the orchestrator from the pack (stubs/workflows/${STUB_FILE})`,
        }));
      }
    }
    // …and every vendored reusable workflow + composite action must be present.
    for (const wf of VENDORED_WORKFLOWS) {
      if (ctx.read(`.github/workflows/${wf}`) === null) {
        out.push(finding(rule, {
          file: `.github/workflows/${wf}`,
          what: `vendored reusable workflow ${wf} is missing`,
          fix: `copy it from the chrome-extension-release pack (stubs/workflows/${wf})`,
        }));
      }
    }
    for (const act of VENDORED_ACTIONS) {
      if (ctx.read(`.github/actions/${act}/action.yml`) === null) {
        out.push(finding(rule, {
          file: `.github/actions/${act}/action.yml`,
          what: `vendored composite action ${act} is missing`,
          fix: `copy it from the chrome-extension-release pack (stubs/actions/${act}/)`,
        }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

const rule = {
  id: 'cer/template-tokens',
  severity: 'blocking',
  description: 'No __TOKEN__ placeholder may survive in the release workflows',
  doc: 'packs/chrome-extension-release/RELEASE.md',
  why: 'the setup contract says: grep for __ afterwards; no token may survive',

  run(ctx) {
    const out = [];
    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null) continue;
      text.split('\n').forEach((line, i) => {
        const m = /__[A-Z_]+__/.exec(line);
        if (m) {
          out.push(finding(rule, {
            file: wf, line: i + 1,
            what: `unreplaced template token ${m[0]}`,
            fix: 'replace it with this repo\'s value (zip name, bump command, …) per the setup steps',
          }));
        }
      });
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { findExtensionManifest } from '../../engine/checks/helpers/chrome-manifest.mjs';

const rule = {
  id: 'cer/version-sync',
  severity: 'blocking',
  description: "The manifest's version is the single source of truth; package.json must equal it",
  doc: 'packs/chrome-extension-release/RELEASE.md',
  why: 'a version that diverges ships the wrong number to the store or refuses to publish',

  run(ctx) {
    const manifestPath = findExtensionManifest(ctx);
    if (!manifestPath) return [];
    let manifest;
    try { manifest = JSON.parse(ctx.read(manifestPath)); } catch { return []; }
    const pkgText = ctx.read('package.json');
    if (pkgText === null) {
      return [finding(rule, {
        file: 'package.json',
        what: 'missing — the release pipeline builds via npm run build at the repo root',
        fix: 'add the root package.json with version equal to the manifest\'s',
      })];
    }
    let pkg;
    try { pkg = JSON.parse(pkgText); } catch { return []; }
    if (manifest.version !== pkg.version) {
      return [finding(rule, {
        file: manifestPath,
        what: `manifest version ${manifest.version} != package.json version ${pkg.version}`,
        fix: 'bump both together — "bump version" edits the manifest and package.json in the same change',
      })];
    }
    return [];
  },
};

export default rule;

