import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { optionalDistNames, importNamesFor, topPackagesOf } from './pyproject.mjs';

// When a lazy import of an optional dependency is guarded with
// `try: import … except ImportError:` and the guard re-raises, the re-raise
// should carry an actionable install hint naming the exact extra — otherwise
// the user hits a bare ModuleNotFoundError from deep inside a backend instead
// of "pip install pkg[extra]". This flags a guard around a declared-optional
// import whose except-body re-raises with no `pip install` hint anywhere in it.
// Repo-state on purpose: an unhelpful guard is a live defect however long ago
// it merged. Advisory: whether a message names the *exact* extra is a wording
// judgment, so this nudges rather than blocks.
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): same gate as the
// sibling top-level rule — the repo must declare optional dependencies in a
// pyproject.toml, and a block is only in scope when ITS OWN try-body imports one
// of those exact packages (so an unrelated `except ImportError` — a fallback
// import, a feature probe — is never touched). Test files and the skill's own
// dir are excluded.
//
// Out of scope, documented, never a false-positive: a probe guard that sets a
// flag instead of re-raising (`except ImportError: HAVE_TF = False`) has no
// `raise`, so it is not flagged — that availability-probe shape (and its
// `# noqa: F401`) is the residue the python pack's RULES.md keeps as prose.
const SELF = 'skills/python-optional-deps/';
const PY_EXT = /\.py$/;
const TESTISH = /(^|\/)(tests?|__tests__)\/|(^|\/)(test_[^/]*|conftest)\.py$|_test\.py$/;
const PYPROJECT = /(^|\/)pyproject\.toml$/;

const indentOf = (s) => s.length - s.trimStart().length;
const isImport = (s) => /^\s*(import|from)\s/.test(s);

// Each try/except ImportError block in `text` whose try-body imports a package
// in `importNames` and whose except-body re-raises with no `pip install` hint,
// as { line } at the offending raise.
function offendingGuards(text, importNames) {
  const lines = text.split('\n');
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    const mtry = /^(\s*)try\s*:/.exec(lines[i]);
    if (!mtry) continue;
    const base = mtry[1].length;
    // try-body: indented lines up to the dedent that ends the block
    let j = i + 1;
    let importsOptional = false;
    for (; j < lines.length; j++) {
      if (lines[j].trim() === '') continue;
      if (indentOf(lines[j]) <= base) break;
      const code = lines[j].split('#')[0];
      if (isImport(code) && topPackagesOf(code).some((p) => importNames.has(p))) importsOptional = true;
    }
    if (!importsOptional) continue;
    if (j >= lines.length || indentOf(lines[j]) !== base || !/^\s*except\b.*\bImportError\b/.test(lines[j])) continue;
    // except-body
    let raiseLine = null;
    let hasHint = false;
    for (let k = j + 1; k < lines.length; k++) {
      if (lines[k].trim() === '') continue;
      if (indentOf(lines[k]) <= base) break;
      if (/\bpip install\b/.test(lines[k])) hasHint = true;
      if (raiseLine === null && /^\s*raise\b/.test(lines[k])) raiseLine = k + 1;
    }
    if (raiseLine !== null && !hasHint) hits.push({ line: raiseLine });
  }
  return hits;
}

function optionalImportNames(ctx) {
  const optional = new Set();
  for (const f of ctx.files.filter((f) => !f.startsWith(SELF) && PYPROJECT.test(f))) {
    for (const n of optionalDistNames(ctx.read(f) ?? '')) optional.add(n);
  }
  return optional.size ? importNamesFor(optional) : null;
}

const rule = {
  id: 'python-optional-import-install-hint',
  severity: 'advisory',
  description: 'A guarded optional import that re-raises does so with a `pip install` hint naming the extra, not a bare ImportError',
  doc: 'skills/python-optional-deps/SKILL.md',
  why: 'a `try/except ImportError` guard that re-raises without an install hint leaves the user a bare ModuleNotFoundError from deep inside a backend instead of the exact `pip install pkg[extra]` that fixes it',

  run(ctx) {
    const importNames = optionalImportNames(ctx);
    if (!importNames) return [];
    const out = [];
    const pyFiles = ctx.files.filter((f) => !f.startsWith(SELF) && PY_EXT.test(f) && !TESTISH.test(f));
    for (const file of pyFiles) {
      const text = ctx.read(file);
      if (text === null) continue;
      for (const { line } of offendingGuards(text, importNames)) {
        out.push(finding(rule, {
          file, line,
          what: 're-raises a missing optional dependency without a `pip install` hint',
          fix: 'raise ImportError from the caught error with a message naming the exact extra — e.g. pip install "pkg[extra]" — so the failure tells the user how to fix it',
        }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { optionalDistNames, importNamesFor, topPackagesOf } from './pyproject.mjs';

// A declared-optional dependency imported at module top level runs at
// `import <pkg>` time — dragging the heavy/native stack (TensorFlow, Torch, a
// native binding) into the dependency-free core and breaking every path for
// anyone who installed the package without that extra. The import belongs
// inside the function/method/__init__ that uses it, so importing the package
// stays cheap. Repo-state on purpose: a leaked top-level import is a live
// core-breakage however long ago it merged.
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check runs on
// EVERY repo, so the gate is what makes the signal false-positive-free — the
// repo must declare optional dependencies in a pyproject.toml
// ([project.optional-dependencies] is the ONLY place a package is DECLARED
// optional), and only those exact packages are in scope. Then, in the project's
// own .py files (test files excluded — a backend-specific test legitimately
// top-level-imports its extra behind an importorskip; the skill's own dir
// excluded so its fixtures never self-flag), a module-top-level (column-0, so
// outside any def/class/try) import of a declared-optional package is the
// violation.
//
// Out of scope, documented, never a false-positive: a top-level import GUARDED
// by try/except is indented (never column 0) so it is not flagged here — that
// shape belongs to the sibling install-hint rule; and a dist whose import name
// is unrelated to its dist name is not mapped (see pyproject.mjs), so it is not
// flagged either.
const SELF = 'skills/python-optional-deps/';
const PY_EXT = /\.py$/;
const TESTISH = /(^|\/)(tests?|__tests__)\/|(^|\/)(test_[^/]*|conftest)\.py$|_test\.py$/;
const PYPROJECT = /(^|\/)pyproject\.toml$/;
const TOP_LEVEL_IMPORT = /^(import|from)\s/; // column 0 — no leading whitespace

function optionalImportNames(ctx) {
  const optional = new Set();
  for (const f of ctx.files.filter((f) => !f.startsWith(SELF) && PYPROJECT.test(f))) {
    for (const n of optionalDistNames(ctx.read(f) ?? '')) optional.add(n);
  }
  return optional.size ? importNamesFor(optional) : null;
}

const rule = {
  id: 'python-optional-import-top-level',
  severity: 'blocking',
  description: 'A declared-optional dependency is imported lazily (inside the code that needs it), never at module top level',
  doc: 'skills/python-optional-deps/SKILL.md',
  why: 'a top-level import runs at `import <pkg>` time, so a package the project itself declared optional drags its heavy/native stack into the dependency-free core and breaks every path for anyone who installed without that extra',

  run(ctx) {
    const importNames = optionalImportNames(ctx);
    if (!importNames) return [];
    const out = [];
    const pyFiles = ctx.files.filter((f) => !f.startsWith(SELF) && PY_EXT.test(f) && !TESTISH.test(f));
    for (const file of pyFiles) {
      const text = ctx.read(file);
      if (text === null) continue;
      text.split('\n').forEach((ln, i) => {
        if (!TOP_LEVEL_IMPORT.test(ln)) return;
        const pkg = topPackagesOf(ln.split('#')[0]).find((p) => importNames.has(p));
        if (pkg) out.push(finding(rule, {
          file, line: i + 1,
          what: `imports the optional dependency "${pkg}" at module top level`,
          fix: 'move the import inside the function/method/__init__ that uses it (guarded by try/except ImportError), so `import <pkg>` stays dependency-free',
        }));
      });
    }
    return out;
  },
};

export default rule;
// Python-packaging knowledge the two optional-dependency checks share: which
// packages THIS repo declared optional, and how a distribution name maps to the
// import name a .py file would write. This is policy specific to the rules, not
// engine mechanism (that lives in engine/checks/helpers per the #351 lesson) — so it stays
// here beside the rules, imported by both. The checks runner only loads
// checks.mjs, so this module is inert to skill discovery.

// The distribution names under [project.optional-dependencies] in a
// pyproject.toml's text. Line-based (the engine carries no TOML parser): find
// the section header, and until the next top-level [header] collect the leading
// package token of every quoted requirement string. Inside that section every
// quoted token is a requirement (the extra-group keys — `yamnet = [ ... ]` —
// are unquoted), so this needs no value/key discrimination. Handles the
// standard table form (grounded in missingbulb/LaughCounter). The rarer inline
// form — `optional-dependencies = { extra = [...] }` under [project] — is not
// parsed: a safe false-negative (nothing flagged), never a false-positive.
export function optionalDistNames(tomlText) {
  const names = new Set();
  let inSection = false;
  for (const raw of tomlText.split('\n')) {
    const header = /^\s*\[([^\]]+)\]/.exec(raw);
    if (header) { inSection = header[1].trim() === 'project.optional-dependencies'; continue; }
    if (!inSection) continue;
    for (const m of raw.matchAll(/["']([^"']+)["']/g)) {
      const name = /^[A-Za-z0-9][A-Za-z0-9._-]*/.exec(m[1].trim());
      if (name) names.add(name[0].toLowerCase());
    }
  }
  return names;
}

// The import top-level package name(s) a set of dist names could appear as.
// Conservative: the name itself, plus '-'/'.' → '_' (the PEP 503-ish normal
// form, e.g. tensorflow-hub → tensorflow_hub). A dist whose import name is
// unrelated to its name (Pillow→PIL, opencv-python→cv2, scikit-learn→sklearn,
// PyYAML→yaml) is deliberately NOT mapped — so it simply isn't flagged, a safe
// false-negative, never a false-positive on an unrelated top-level import.
export function importNamesFor(distSet) {
  const imports = new Set();
  for (const d of distSet) {
    imports.add(d);
    imports.add(d.replace(/[-.]/g, '_'));
  }
  return imports;
}

// The top-level package names an `import`/`from` statement pulls in, lowercased
// for comparison against importNamesFor's set. `from a.b import c` → a (a
// relative `from . import x` yields nothing); `import a.b as x, c` → a, c.
// Callers strip trailing comments before passing the line.
export function topPackagesOf(importLine) {
  const line = importLine.trim();
  let m;
  if ((m = /^from\s+([.\w]+)\s+import\b/.exec(line))) {
    return m[1].startsWith('.') ? [] : [m[1].split('.')[0].toLowerCase()];
  }
  if ((m = /^import\s+(.+)$/.exec(line))) {
    return m[1].split(',')
      .map((part) => part.trim().split(/\s+as\s+/)[0].trim().split('.')[0].toLowerCase())
      .filter((name) => name && !name.startsWith('.'));
  }
  return [];
}
import optionalImportTopLevel from './optional-import-lazy.mjs';
import optionalImportInstallHint from './optional-import-install-hint.mjs';

// The check-the-work rules validating this skill's action — wiring a Python
// package's optional heavy/native dependency. Discovered by engine/pack_loader/pack-registry.mjs
// and run at every Stop and in CI; each is inert until the repo declares
// optional dependencies in a pyproject.toml (its RELEVANCE FIRST gate). The
// failure messages carry the rules — there is deliberately no prose copy to
// drift from. The residue that has no false-positive-free signature (which deps
// belong in the base set, the stdlib-backend architecture, the F401
// availability-probe suppression) stays as prose in the python pack's RULES.md.
export default [optionalImportTopLevel, optionalImportInstallHint];

