// fixtures never self-flag on the corpus repo; test/fixture files are excluded
// from the acquisition scan, where a mocked `getUserMedia` opens no real device.
const SELF = 'skills/web-speech-io/';
const SOURCE = /\.(mjs|cjs|jsx?|tsx?)$/;
const TEST = /\.(test|spec)\.[cm]?jsx?$|(^|\/)(__tests__|__mocks__|fixtures?)\//;

const GET_USER_MEDIA = /\bgetUserMedia\s*\(/;
const RECOGNIZER = /\b(webkitSpeechRecognition|SpeechRecognition)\b/;
const START = /\.start\s*\(/;
// A pagehide teardown, however it is registered.
const PAGEHIDE = /addEventListener\s*\(\s*['"`]pagehide['"`]|\bonpagehide\b/;

// The 1-indexed line where a file opens the microphone, or null. A `getUserMedia`
// call is the unambiguous anchor; failing that, a file that both names the
// recognizer API and `.start()`s something is driving a live recognizer — anchor
// on the recognizer reference.
function acquisitionLine(text) {
  const lines = text.split('\n');
  const gum = lines.findIndex((l) => GET_USER_MEDIA.test(l));
  if (gum !== -1) return gum + 1;
  if (RECOGNIZER.test(text) && START.test(text)) {
    const ref = lines.findIndex((l) => RECOGNIZER.test(l));
    if (ref !== -1) return ref + 1;
  }
  return null;
}

const rule = {
  id: 'web-speech-capture-released-on-pagehide',
  severity: 'blocking',
  description: 'A repo that opens the microphone releases it on pagehide (bfcache-safe teardown), not just on implicit page unload',
  doc: 'skills/web-speech-io/SKILL.md',
  why: 'the browser does not reliably free the mic on implicit page teardown — a page frozen into the bfcache is suspended, not destroyed, so a live recognizer or getUserMedia stream keeps the device (and the recording indicator) on until a pagehide handler stops it',

  run(ctx) {
    const source = ctx.files.filter((f) => !f.startsWith(SELF) && SOURCE.test(f));
    // Conformance is repo-wide: a pagehide teardown in ANY owning context clears it.
    if (source.some((f) => PAGEHIDE.test(ctx.read(f) ?? ''))) return [];
    const out = [];
    for (const f of source) {
      if (TEST.test(f)) continue; // a mocked getUserMedia in a test opens no device
      const text = ctx.read(f);
      if (text === null) continue;
      const line = acquisitionLine(text);
      if (line === null) continue;
      out.push(finding(rule, {
        file: f, line,
        what: 'opens the microphone (getUserMedia / a speech recognizer) but no source file releases the capture on `pagehide`',
        fix: 'in whichever page owns the capture, add `window.addEventListener("pagehide", …)` that aborts the recognizer and stops any getUserMedia tracks (and stop a preflight capture in a `finally`) — pagehide fires on real unload AND bfcache freeze, unlike beforeunload; if the capture lives in an offscreen document torn down via closeDocument, accept this rule for that file with a reason',
      }));
    }
    return out;
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { matchingLines } from '../../../../engine/checks/helpers/line-scanning.mjs';

// Chrome ships speech recognition only under the webkit-prefixed constructor;
// other Chromium contexts (headless, non-Chromium browsers, the test binding)
// expose neither. Constructing `new webkitSpeechRecognition()` directly — with
// no feature-detect of the unprefixed `SpeechRecognition` name — throws a bare
// ReferenceError wherever the prefixed global is absent, taking down the whole
// module instead of degrading to a no-op. The portable form resolves the
// constructor once (`globalThis.SpeechRecognition ?? globalThis.webkitSpeechRecognition`)
// and gates an `available` flag on it existing.
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check runs on
// EVERY repo, so the gate is the anti-pattern itself — a source file that
// directly constructs the prefixed recognizer AND never mentions the unprefixed
// `SpeechRecognition` name (its presence anywhere, in a `??`/`||` fallback or a
// feature test, means the file is aware of both and is not scanned — a
// conservative gate that would rather miss than false-flag). Advisory: a lone
// direct construction is a smell to judge, not proof of a break. The skill's own
// directory is excluded so its fixtures never self-flag on the corpus repo.
const SELF = 'skills/web-speech-io/';
const SOURCE = /\.(mjs|cjs|jsx?|tsx?)$/;
const DIRECT_PREFIXED = /new\s+webkitSpeechRecognition\s*\(/;

// The unprefixed identifier, NOT the webkit-prefixed one — a stripped copy of
// the text (prefixed occurrences removed) makes the word-boundary test exact.
function featureDetects(text) {
  return /\bSpeechRecognition/.test(text.replace(/webkitSpeechRecognition/g, ''));
}

const rule = {
  id: 'web-speech-recognition-feature-detected',
  severity: 'advisory',
  description: 'Speech recognition is obtained through a feature-detect, not by constructing the webkit-prefixed API directly',
  doc: 'skills/web-speech-io/SKILL.md',
  why: 'Chrome exposes recognition only under the webkit prefix and headless/non-Chromium contexts expose neither, so `new webkitSpeechRecognition()` with no unprefixed fallback throws a bare ReferenceError wherever the prefixed global is absent instead of degrading to a no-op',

  run(ctx) {
    const files = ctx.files.filter((f) =>
      !f.startsWith(SELF) && SOURCE.test(f) && !featureDetects(ctx.read(f) ?? ''));
    return matchingLines(ctx, files, DIRECT_PREFIXED).map(({ file, line }) => finding(rule, {
      file, line,
      what: 'constructs the webkit-prefixed recognizer directly with no unprefixed SpeechRecognition fallback',
      fix: 'resolve the constructor once via `globalThis.SpeechRecognition ?? globalThis.webkitSpeechRecognition` and gate an availability flag on it existing, so absent-API contexts degrade to a no-op',
    }));
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';

// The Web Speech recognition API and speechSynthesis are Window-scoped: they
// live on `window`/a document, which an MV3 background service worker does not
// have. Referencing them in the worker throws (recognition) or leaves the global
// undefined (synthesis) at runtime — a listen or speak that silently never
// happens. chrome.tts is the extension-only TTS engine that DOES run in the
// worker, so synthesis has a real worker path; recognition has none and must
// move to a document context. Repo-state on purpose: a worker that references
// one of these is a live break however long ago it merged.
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check runs on
// EVERY repo, so the gate is narrow — only the file an MV3 manifest.json names
// as `background.service_worker`, resolved relative to the manifest, and only
// when that file is the project's OWN authored source (ctx.files, so a built /
// bundled worker artifact that merely concatenates document-context source is
// out of scope — the same signature-less residue google-id-token-validation
// documents for code-form verifiers). No MV3 manifest, or a manifest that
// bundles its worker, means the check stays silent. The skill's own directory is
// excluded so its fixtures never self-flag on the corpus repo.
const SELF = 'skills/web-speech-io/';
const RECOGNITION = /\b(webkitSpeechRecognition|SpeechRecognitionPhrase|SpeechRecognition)\b/;
const SYNTHESIS = /\b(speechSynthesis|SpeechSynthesisUtterance)\b/;

// Resolve a manifest-relative path ("background.js", "src/sw.js") against the
// manifest's directory, normalized to the '/'-separated form ctx.files uses.
function resolveFrom(manifestPath, rel) {
  const dir = manifestPath.includes('/') ? manifestPath.slice(0, manifestPath.lastIndexOf('/')) : '';
  const parts = [];
  for (const seg of `${dir}/${rel}`.split('/')) {
    if (seg === '' || seg === '.') continue;
    if (seg === '..') parts.pop();
    else parts.push(seg);
  }
  return parts.join('/');
}

// The file an MV3 manifest names as its background service worker, when that
// file is the project's own authored source. [] otherwise.
function serviceWorkers(ctx) {
  const out = [];
  for (const f of ctx.files) {
    if (f.startsWith(SELF) || !/(^|\/)manifest\.json$/.test(f)) continue;
    let manifest;
    try { manifest = JSON.parse(ctx.read(f) ?? ''); } catch { continue; }
    if (!manifest || manifest.manifest_version !== 3) continue;
    const sw = manifest.background?.service_worker;
    if (typeof sw !== 'string' || !sw) continue;
    const resolved = resolveFrom(f, sw);
    if (ctx.files.includes(resolved)) out.push(resolved);
  }
  return out;
}

const rule = {
  id: 'web-speech-no-window-api-in-service-worker',
  severity: 'blocking',
  description: 'An MV3 background service worker does not reference a Window-scoped Web Speech API (recognition or speechSynthesis)',
  doc: 'skills/web-speech-io/SKILL.md',
  why: 'the recognition API and speechSynthesis live on window/a document, which a service worker has no access to — referencing them there throws or leaves the global undefined at runtime, so the listen or speak silently never happens',

  run(ctx) {
    const out = [];
    for (const sw of serviceWorkers(ctx)) {
      const text = ctx.read(sw);
      if (text === null) continue;
      text.split('\n').forEach((ln, i) => {
        if (RECOGNITION.test(ln)) {
          out.push(finding(rule, {
            file: sw, line: i + 1,
            what: 'constructs or references the Web Speech recognition API in the MV3 service worker',
            fix: 'recognition needs a document — move the listening half to a content script, side panel, popup, or offscreen document, and keep the worker for document-free work',
          }));
        } else if (SYNTHESIS.test(ln)) {
          out.push(finding(rule, {
            file: sw, line: i + 1,
            what: 'references speechSynthesis in the MV3 service worker, where it is undefined',
            fix: 'speak from the worker with chrome.tts (extension-only, needs the "tts" permission, immune to page autoplay gating); reserve speechSynthesis for a document context',
          }));
        }
      });
    }
    return out;
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';

// One value in two roles: the client requests the ID token FOR the client id
// (the token's audience) and the validator EXPECTS it — independently-edited
// copies drift, and a drifted pair rejects every token with an opaque 401.
// Scoped to the work: legacy duplicates on the base are the world, not this
// change. The literal itself is the relevance gate; the skill's own directory
// is excluded so its fixtures never self-flag on the corpus repo.
const SELF = 'skills/google-id-token-validation/';
const CLIENT_ID = /[A-Za-z0-9][\w-]*\.apps\.googleusercontent\.com/g;

const rule = {
  id: 'google-client-id-single-origin',
  severity: 'advisory',
  description: 'A change does not add a copy of a Google OAuth client-id literal that already lives in another file',
  doc: 'skills/google-id-token-validation/SKILL.md',
  scope: 'work',
  why: 'the client requests the token for this id and the validator expects it as audience — one value; independently-edited copies drift, and a drifted pair rejects every well-formed token with an opaque 401',

  run(work) {
    const out = [];
    for (const { file, line, text } of work.addedLines()) {
      if (file.startsWith(SELF)) continue;
      for (const literal of new Set([...text.matchAll(CLIENT_ID)].map((m) => m[0]))) {
        const elsewhere = work.filesContaining(literal).filter((f) => f !== file && !f.startsWith(SELF));
        if (elsewhere.length === 0) continue;
        out.push(finding(rule, {
          file, line,
          what: `adds a copy of the OAuth client id ${literal}, already present in ${elsewhere.join(', ')}`,
          fix: 'derive it from the existing origin (import the constant, read the manifest, pass a deploy parameter) instead of pasting a second copy; confirm a cross-deploy-unit pair is deliberate',
        }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { matchingLines } from '../../../../engine/checks/helpers/line-scanning.mjs';

// A Google ID token carries an email claim regardless of verification; it is
// trustworthy only together with email_verified. Two static signatures in
// handler code: (a) reading the email claim in a file that never mentions
// email_verified; (b) comparing email_verified to a boolean with strict
// equality behind an API Gateway JWT authorizer, which stringifies claims — the
// claim arrives as the string 'true', so a strict boolean compare silently
// rejects every genuinely-verified user. Repo-state on purpose: both are live
// auth defects however long ago they merged.
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check runs on
// EVERY repo, and email_verified is standard OIDC, so two gates keep this
// Google-scoped: per file, only non-test code files handling verified-token
// claims (an authorizer context or a verify call); per repo, only when some
// file carries a Google identity marker (the accounts issuer or a
// googleusercontent client id) — evaluated lazily, once a candidate finding
// exists. The skill's own directory is excluded so its fixtures never
// self-flag on the corpus repo.
const SELF = 'skills/google-id-token-validation/';
const CODE_EXT = /\.(mjs|cjs|jsx?|tsx?|py)$/;
const TESTISH = /(^|\/)(tests?|__tests__|spec)\/|\.(test|spec)\./;
const CLAIMS_CONTEXT = /requestContext\s*\.\s*authorizer|jwt\.claims|verifyIdToken|jwtVerify/;
const EMAIL_ACCESS = /\b(claims|payload)\??\.email\b(?!_)|(claims|payload)\[['"]email['"]\]/;
const STRICT_BOOL = /email_verified\W{0,4}\s*[!=]==\s*(true|false)\b/;
const GOOGLE_MARKER = /accounts\.google\.com|\.apps\.googleusercontent\.com/;

const rule = {
  id: 'google-token-email-verified',
  severity: 'blocking',
  description: 'Handler code trusts a Google ID token\'s email claim only when email_verified says so, compared as the authorizer delivers it',
  doc: 'skills/google-id-token-validation/SKILL.md',
  why: 'a Google ID token carries email regardless of verification — an action gated on the bare claim trusts an address Google has not verified; and behind an API Gateway JWT authorizer the claim arrives as a string, so a strict boolean compare silently rejects every genuinely-verified user',

  run(ctx) {
    const handlers = ctx.files.filter((f) =>
      !f.startsWith(SELF) && CODE_EXT.test(f) && !TESTISH.test(f) && CLAIMS_CONTEXT.test(ctx.read(f) ?? ''));
    const candidates = [
      ...matchingLines(ctx, handlers.filter((f) => !/email_verified/.test(ctx.read(f) ?? '')), EMAIL_ACCESS)
        .map(({ file, line }) => finding(rule, {
          file, line,
          what: 'reads the token\'s email claim but never checks email_verified',
          fix: 'gate any identity-bearing action on the email_verified claim being true (behind an API Gateway JWT authorizer it arrives as the string \'true\')',
        })),
      ...matchingLines(ctx, handlers.filter((f) => /requestContext/.test(ctx.read(f) ?? '')), STRICT_BOOL)
        .map(({ file, line }) => finding(rule, {
          file, line,
          what: 'compares email_verified to a boolean with strict equality behind an API Gateway authorizer',
          fix: 'compare against the string \'true\' (or coerce) — the authorizer stringifies claims, so a strict boolean compare rejects every verified user',
        })),
    ];
    if (candidates.length === 0) return [];
    const googleRepo = ctx.files.some((f) => !f.startsWith(SELF) && GOOGLE_MARKER.test(ctx.read(f) ?? ''));
    return googleRepo ? candidates : [];
  },
};

export default rule;
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { matchingLines } from '../../../../engine/checks/helpers/line-scanning.mjs';

// A Google ID token is accepted on three things: signature, issuer, audience.
// Every Google-issued token shares the one issuer, so a validator whose
// expected audience is unset accepts tokens minted for ANY Google OAuth client
// — an authentication bypass that looks completely valid. Repo-state on
// purpose: a pre-existing unset audience is a live bypass and must keep firing
// until fixed, however long ago it merged.
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check runs on
// EVERY repo, so the gate is narrow — only config-format files (yaml/json/toml/
// tf) that use the word "issuer" and carry the bare Google issuer origin
// (scheme + host with no path; a path form is a client-side OAuth URL, not an
// issuer). Code-form verifiers (jose, jsonwebtoken) have no reliable
// file-scoped signature and are not scanned. The skill's own directory is
// excluded so its fixtures never self-flag on the corpus repo.
const SELF = 'skills/google-id-token-validation/';
const CONFIG_EXT = /\.(ya?ml|json|toml|tf)$/;
const BARE_ISSUER = /https:\/\/accounts\.google\.com(?![\w/.-])/;
const ISSUER_WORD = /issuer/i;
const AUD_MENTION = /\baud(ience)?\b/i;
const EMPTY_AUD = /aud(ience)?["']?\s*[:=]\s*(\[\s*\]|""|'')/i;

const rule = {
  id: 'google-token-audience-pinned',
  severity: 'blocking',
  description: 'A validator config declaring the Google accounts issuer pins a non-empty expected audience',
  doc: 'skills/google-id-token-validation/SKILL.md',
  why: 'every Google-issued ID token shares that issuer, so signature + issuer alone accept a token minted for any Google OAuth client — the audience claim is the only thing that scopes a token to this app, and an unset audience is a full authentication bypass',

  run(ctx) {
    const configs = ctx.files.filter((f) => !f.startsWith(SELF) && CONFIG_EXT.test(f));
    return matchingLines(ctx, configs, BARE_ISSUER)
      .filter(({ file }) => {
        const text = ctx.read(file) ?? '';
        return ISSUER_WORD.test(text) && !(AUD_MENTION.test(text) && !EMPTY_AUD.test(text));
      })
      .map(({ file, line }) => finding(rule, {
        file, line,
        what: 'declares the Google accounts issuer with no (or an explicitly empty) expected audience',
        fix: 'configure the validator\'s audience to your exact OAuth web-application client id, next to the issuer; never leave it unset',
      }));
  },
};

export default rule;

