import { finding } from '../../../../engine/checks/helpers/findings.mjs';

// In-session routine/worker code reaches GitHub through the session's MCP tools —
// never a REST client + GITHUB_TOKEN. This is the corollary of the dispatch-only
// executor rule (SKILL.md): a routine's own steps operate over the repos the session
// was granted, which the MCP GitHub tools already cover, so they need no token; only
// a capability the session LACKS (an account-wide credential, a sandbox-unreachable
// surface) belongs in a workflow_dispatch-only executor that runs in CI with that
// token.
//
// So a REST client, a raw api.github.com fetch, or a GITHUB_TOKEN read in in-session
// code is the tell that the code was built as if it were the CI executor — it cannot
// authenticate in the MCP-only session it is scheduled in. This is exactly the
// regression that turned the (since-retired) fleet daily maintenance into a no-op
// day when its planner + migration passes were (re)written as token-authed REST node
// scripts: every step 401'd because the scheduled session has no shell GitHub REST
// credential.
//
// RELEVANCE (see engine/checks/README.md "Adding a rule" / routine-structure.mjs): a skill
// check runs on every repo, so it must detect relevance before asserting. Here the
// scope IS the relevance gate — only .mjs under routines/ or migrations/ (the
// in-session code surface). A dispatch-only executor's own code (e.g. a census
// invoked by a workflow) lives outside those trees and keeps its REST client
// legitimately, so it is never scanned.
//
// A scheduled task's `tasks/<name>/` tree is deliberately NOT in scope: a task's
// `agent_preprocessing` worker.mjs runs as an Action-side subprocess with an
// injected GITHUB_TOKEN, the one sanctioned non-MCP surface
// (per-project-scheduling DESIGN §10), so a REST client there is correct, not a
// smell. The former `run_daily/` arm retired with the central planner (#394): no
// repo carries run_daily descriptors any more, and the per-repo scheduler
// dispatches tasks/, not run_daily/.

const IN_SESSION = [/^routines\//, /^migrations\//];
const inSession = (f) => f.endsWith('.mjs') && !f.endsWith('.test.mjs') && IN_SESSION.some((re) => re.test(f));

// Actionable REST/token smells — matched as code, not prose mentions (a comment
// saying "no GITHUB_TOKEN here" carries none of these exact forms).
const SMELLS = [
  { re: /process\.env\.(?:GITHUB_TOKEN|GH_TOKEN|FLEET_GITHUB_TOKEN)/, what: 'reads a GitHub REST token from the environment' },
  { re: /\bmakeGh\s*\(|from\s+['"][^'"]*\bfleet-api/, what: 'uses the REST client (makeGh / fleet-api)' },
  { re: /['"`]https?:\/\/api\.github\.com/, what: 'targets the GitHub REST API (api.github.com) directly' },
];

const isComment = (ln) => { const t = ln.trimStart(); return t.startsWith('//') || t.startsWith('*') || t.startsWith('/*'); };

const rule = {
  id: 'in-session-github-access',
  severity: 'blocking',
  description: 'In-session routine code reaches GitHub through the MCP tools, not a REST client + GITHUB_TOKEN',
  doc: 'skills/unattended-agents/SKILL.md',
  why: 'a routine runs in an MCP-only session with no shell GitHub REST credential; a REST client / GITHUB_TOKEN in its own steps cannot authenticate there — that belongs in a workflow_dispatch-only CI executor',

  run(ctx) {
    const out = [];
    for (const f of ctx.files.filter(inSession)) {
      const text = ctx.read(f);
      if (text === null) continue;
      text.split('\n').forEach((ln, i) => {
        if (isComment(ln)) return;
        for (const s of SMELLS) {
          if (s.re.test(ln)) {
            out.push(finding(rule, {
              file: f, line: i + 1,
              what: `${s.what} — in-session routine code has no REST credential`,
              fix: 'reach GitHub through the session’s injected MCP-backed I/O (a gh(path) reader for reads, a semantic io object for writes); move any work that needs an account-wide credential into a workflow_dispatch-only executor',
            }));
            break;
          }
        }
      });
    }
    return out;
  },
};

export default rule;
import { dirname, join, basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';

// A routine (or a per-project-scheduling task, §1) is a folder whose entry point is
// `routine.md` OR `task.md`, alongside the deterministic scripts it invokes. This
// check asserts the prose↔script wiring that the unattended-agents skill mandates,
// for both shapes: a legacy `dev/routines/<name>/routine.md` and a converted
// `.../tasks/<name>/task.md` earn the same guard (a task folder's `task.mjs`
// carries the declaration; its `task.md` is the worker prose the scripts hang off).
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check has no
// declaration gate — the engine runs it on EVERY repo, including ones with no
// routines — so `run` must detect relevance before asserting anything. Here the
// signal is a `routine.md`/`task.md` existing: `routineDirs` is empty on any repo
// without one, every loop below is over an empty set, and the check no-ops. Keep
// that gate narrow and up front; a broad signal would fire false findings everywhere.
const ENTRY_NAMES = ['routine.md', 'task.md'];
const isEntry = (f) => ENTRY_NAMES.includes(basename(f));
const PHASE_SCRIPTS = ['preconditions.sh', 'postconditions.sh'];

// Direct-child files of dir `d` within `files` matching `pred` (not descendants).
function children(files, d, pred) {
  const prefix = d ? d + '/' : '';
  return files.filter((f) => {
    if (!f.startsWith(prefix)) return false;
    const rel = f.slice(prefix.length);
    return rel.length > 0 && !rel.includes('/') && pred(rel);
  });
}

const rule = {
  id: 'routine-structure',
