  }

  if (!lineJobs.length) return;
  lines().forEach((ln, i) => {
    for (const { j, eligible } of lineJobs) {
      if (j.spec.skipLinesMatching?.test(ln)) continue;
      for (const a of eligible) {
        const m = ln.match(a.match);
        if (!m || a.unlessLineMatches?.test(ln)) continue;
