    ...meta('fx-pass-a'), files: /\.txt$/, line: [{ match: /aa/, what: 'a', fix: 'f' }],
  });
  const b = patternRule({
    ...meta('fx-pass-b'), files: /\.txt$/, file: [{ require: /present/, what: 'b', fix: 'f' }],
  });
  const root = makeRepo({ changed: { 'one.txt': 'aa\npresent\n', 'two.txt': 'aa\n' } });
  try {
