      if (globs.some((re) => re.test(path) || re.test(base))) continue;
      const vars = { path, ...(m.groups ?? {}) };
      j.out.push(finding(j.rule, { file: path, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
