        !ctx.files.some((f) => !excluded(f, j.spec.excludeFiles) && marker.test(ctx.read(f) ?? ''))) {
      j.out.length = 0;
    }
  }
  return res;
}

export function patternRule(spec) {
  const rule = {
    id: spec.id,
    severity: spec.severity,
    description: spec.description,
    doc: spec.doc,
    why: spec.why,
    spec,
    run(ctx) { return results(ctx).get(rule); },
  };
  REGISTRY.push(rule);
  return rule;
}

